-- Confirmed AQA core courses for the 2027 student cohort.
-- Combined Science: Trilogy is the agreed working assumption and can be
-- replaced by a later migration if entry code 8465 (Synergy) is confirmed.
PRAGMA foreign_keys = ON;

INSERT OR IGNORE INTO subjects (id, name, exam_board, specification_code)
VALUES
  ('subject-mathematics', 'Mathematics', 'AQA', '8300'),
  ('subject-english-language', 'English Language', 'AQA', '8700'),
  ('subject-english-literature', 'English Literature', 'AQA', '8702'),
  ('subject-combined-science', 'Combined Science', 'AQA', '8464');

UPDATE subjects SET exam_board = 'AQA', specification_code = '8300', updated_at = CURRENT_TIMESTAMP
WHERE id = 'subject-mathematics';
UPDATE subjects SET exam_board = 'AQA', specification_code = '8700', updated_at = CURRENT_TIMESTAMP
WHERE id = 'subject-english-language';
UPDATE subjects SET exam_board = 'AQA', specification_code = '8702', updated_at = CURRENT_TIMESTAMP
WHERE id = 'subject-english-literature';
UPDATE subjects SET exam_board = 'AQA', specification_code = '8464', updated_at = CURRENT_TIMESTAMP
WHERE id = 'subject-combined-science';

UPDATE student_subjects
SET tier = 'higher',
    options_json = json_set(options_json, '$.configuration', 'confirmed'),
    updated_at = CURRENT_TIMESTAMP
WHERE subject_id = 'subject-mathematics';

UPDATE student_subjects
SET tier = 'not_applicable',
    options_json = json_set(options_json, '$.configuration', 'confirmed'),
    updated_at = CURRENT_TIMESTAMP
WHERE subject_id = 'subject-english-language';

UPDATE student_subjects
SET tier = 'not_applicable',
    options_json = json_set(
      json_set(
        json_set(
          json_set(json_set(options_json, '$.configuration', 'confirmed'), '$.shakespeare', 'Macbeth'),
          '$.nineteenthCenturyNovel', 'A Christmas Carol'
        ),
        '$.modernText', 'An Inspector Calls'
      ),
      '$.poetryCluster', 'Power and Conflict'
    ),
    updated_at = CURRENT_TIMESTAMP
WHERE subject_id = 'subject-english-literature';

UPDATE student_subjects
SET tier = 'higher',
    options_json = json_set(
      json_set(json_set(options_json, '$.configuration', 'confirmed'), '$.course', 'Trilogy'),
      '$.courseStatus', 'working assumption'
    ),
    updated_at = CURRENT_TIMESTAMP
WHERE subject_id = 'subject-combined-science';

DELETE FROM course_components
WHERE subject_id IN ('subject-mathematics', 'subject-english-language', 'subject-english-literature', 'subject-combined-science');

