INSERT INTO subject_revision_guides
  (subject_id, exam_summary, assessment_objectives_json, exam_tips_json, specification_url, assessment_resources_url, provisional, verified_at)
VALUES
  ('subject-mathematics', 'AQA GCSE Mathematics 8300 Higher: three 1 hour 30 minute papers of 80 marks each. Paper 1 is non-calculator; Papers 2 and 3 allow a calculator. Content from any topic may appear on any paper.', '["AO1: use and apply standard techniques","AO2: reason, interpret and communicate mathematically","AO3: solve problems within mathematics and other contexts"]', '["Show complete working even when using a calculator","Check units, rounding and whether an answer is reasonable","Practise unfamiliar multi-step problems as well as routine methods","Learn the required formulae and know how to use the supplied formulae sheet"]', 'https://www.aqa.org.uk/subjects/mathematics/gcse/mathematics-8300/specification', 'https://www.aqa.org.uk/subjects/mathematics/gcse/mathematics-8300/assessment-resources', 0, '2026-09-26'),
  ('subject-english-language', 'AQA GCSE English Language 8700: Paper 1 Explorations in creative reading and writing and Paper 2 Writers viewpoints and perspectives, each 1 hour 45 minutes, 80 marks and 50%. Spoken Language is separately endorsed.', '["AO1: identify and interpret information and ideas","AO2: explain and analyse language and structure","AO3: compare writers ideas and perspectives","AO4: evaluate texts critically","AO5: communicate clearly and imaginatively for audience and purpose","AO6: use accurate vocabulary, sentences, spelling and punctuation","AO7-AO9: spoken presentation, response and Standard English"]', '["Use short, precise evidence and analyse its effect","Answer the exact focus and source lines in each reading question","Plan writing for audience, purpose and form","Reserve time to check paragraphing, sentences, spelling and punctuation"]', 'https://www.aqa.org.uk/subjects/english/gcse/english-8700/specification', 'https://www.aqa.org.uk/subjects/english/gcse/english-8700/assessment-resources', 0, '2026-09-26'),
  ('subject-english-literature', 'AQA GCSE English Literature 8702: Paper 1 Macbeth and A Christmas Carol (1 hour 45 minutes, 64 marks, 40%); Paper 2 An Inspector Calls, Power and Conflict anthology and unseen poetry (2 hours 15 minutes, 96 marks, 60%). Exams are closed book.', '["AO1: respond critically and use textual references","AO2: analyse language, form and structure","AO3: show understanding of texts and contexts","AO4: use accurate vocabulary, sentences, spelling and punctuation"]', '["Learn flexible short quotations for each set text and anthology poem","Build an argument that answers the question rather than retelling the plot","Connect methods to meanings and relevant context","Practise selecting comparison poems by theme and method","For extracts, analyse the passage and connect it to the whole text"]', 'https://www.aqa.org.uk/subjects/english/gcse/english-literature-8702/specification', 'https://www.aqa.org.uk/subjects/english/gcse/english-literature-8702/assessment-resources', 0, '2026-09-26'),
  ('subject-combined-science', 'AQA Combined Science: Trilogy 8464 Higher: six 1 hour 15 minute papers of 70 marks each, with two Biology, two Chemistry and two Physics papers. Each paper is 16.7% of the double award. Trilogy is the current working course assumption.', '["AO1: demonstrate knowledge and understanding of scientific ideas, techniques and procedures","AO2: apply knowledge and understanding of scientific ideas, enquiry, techniques and procedures","AO3: analyse information and ideas, interpret and evaluate, make judgements and improve procedures"]', '["Revise required practical methods, variables, risks, graphs and evaluation","Learn equations and practise rearranging and substituting with units","Use precise scientific vocabulary in explanations","Practise applying familiar knowledge to unfamiliar contexts","Check the mock or entry code is 8464H; replace this map if 8465H is confirmed"]', 'https://www.aqa.org.uk/subjects/science/gcse/science-8464/specification', 'https://www.aqa.org.uk/subjects/science/gcse/science-8464/assessment-resources', 0, '2026-09-26')
ON CONFLICT(subject_id) DO UPDATE SET
  exam_summary = excluded.exam_summary,
  assessment_objectives_json = excluded.assessment_objectives_json,
  exam_tips_json = excluded.exam_tips_json,
  specification_url = excluded.specification_url,
  assessment_resources_url = excluded.assessment_resources_url,
  provisional = excluded.provisional,
  verified_at = excluded.verified_at,
  updated_at = CURRENT_TIMESTAMP;

DELETE FROM revision_resources
WHERE subject_id IN ('subject-mathematics', 'subject-english-language', 'subject-english-literature', 'subject-combined-science');

